const assets = ports.loadAssets(sceneId)
const glyphs = ports.loadGlyphs().catch((error: unknown) => {
    ports.warn('[bootstrap] loadGlyphs failed, text will render as tofu:', error)
    return undefined
  })
const dialog = ports.loadDialogAssets()
const resourcesReady = Promise.all([
  assets,
  Promise.race([glyphs, Promise.all([assets, dialog]).then(() => undefined)]),
  dialog,
])
